import pyomo.environ as pyo

DATA = {
    "nodes": ["E", "F", "G", "H", "I"],
    "depot_index": 0,
    "cost": {
        ("E", "F"): 65, ("E", "G"): 10, ("E", "H"): 25, ("E", "I"): 82,
        ("F", "E"): 65, ("F", "G"): 98, ("F", "H"): 42, ("F", "I"): 26,
        ("G", "E"): 10, ("G", "F"): 98, ("G", "H"): 75, ("G", "I"): 72,
        ("H", "E"): 25, ("H", "F"): 42, ("H", "G"): 75, ("H", "I"): 46,
        ("I", "E"): 82, ("I", "F"): 26, ("I", "G"): 72, ("I", "H"): 46,
    },
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    nodes = d["nodes"]
    n = len(nodes)
    depot = d["depot_index"]
    idx = {name: k for k, name in enumerate(nodes)}

    # arc cost dictionary keyed by (i, j) integer indices
    cost_by_index = {}
    for (a, b), c in d["cost"].items():
        cost_by_index[(idx[a], idx[b])] = c

    # arcs: all ordered pairs i != j
    arcs = [(i, j) for i in range(n) for j in range(n) if i != j]

    m = pyo.ConcreteModel()
    m.N = pyo.RangeSet(0, n - 1)
    m.A = pyo.Set(initialize=arcs, dimen=2)

    # x[i,j] = 1 if travel directly from i to j
    m.x = pyo.Var(m.A, domain=pyo.Binary)

    # MTZ order variables; depot anchored at 1, others in [2, n]
    m.u = pyo.Var(m.N, domain=pyo.NonNegativeReals)
    for i in m.N:
        if i == depot:
            m.u[i].setlb(1)
            m.u[i].setub(1)
        else:
            m.u[i].setlb(2)
            m.u[i].setub(n)

    # objective: minimize total delivery cost
    def obj_rule(m):
        return sum(cost_by_index[(i, j)] * m.x[i, j] for (i, j) in m.A)
    m.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # each node: exactly one outgoing arc (== 1)
    def out_rule(m, i):
        return sum(m.x[i, j] for j in m.N if (i, j) in arcs) == 1
    m.out_arc = pyo.Constraint(m.N, rule=out_rule)

    # each node: exactly one incoming arc (== 1)
    def in_rule(m, j):
        return sum(m.x[i, j] for i in m.N if (i, j) in arcs) == 1
    m.in_arc = pyo.Constraint(m.N, rule=in_rule)

    # subtour elimination (MTZ): u[j] >= u[i] + 1 - n*(1 - x[i,j])
    # applies for arcs among non-depot nodes; depot arcs handled by fixing u[depot]=1
    def mtz_rule(m, i, j):
        return m.u[j] >= m.u[i] + 1 - n * (1 - m.x[i, j])
    m.mtz = pyo.Constraint(
        [(i, j) for (i, j) in arcs if i != depot and j != depot],
        rule=mtz_rule,
    )

    return m
